# frozen_string_literal: true

# Codegen for the committed build artifacts, `pulpmesh/templates.rb` and
# `pulpmesh/assets.rb`. Runs on CRuby, never inside the compiled binary: Erubi is
# a dev-machine tool here, like a formatter, and is not a spin dependency.
#
# `spin.toml` has no pre-build hook, so the generated files are committed. The
# staleness guard in test/ regenerates and diffs to catch an edit that skipped
# this task.

require "erubi"
require "kramdown"

ROOT = File.expand_path("..", __dir__)

# `render` in site.rb dispatches on the gem's template filenames, so the mapping
# from filename to method name lives here and nowhere else.
TEMPLATES = {
  "post.html.erb" => "render_post",
  "index.html.erb" => "render_index",
  "404.html.erb" => "render_404",
  "rss.xml.erb" => "render_rss"
}.freeze

def generated_templates
  bodies = TEMPLATES.map do |file, method|
    source = File.read(File.join(ROOT, "templates", file))
    # trim: true matches the gem's `trim_mode: "-"`; escapefunc routes a future
    # `<%== %>` to Context#h rather than to CGI, which spinel does not have.
    src = Erubi::Engine.new(source, trim: true, escapefunc: "h").src
    # Emitted at column zero: the string literals span lines, so indenting them
    # to match the surrounding nesting would inject that indentation into every
    # rendered page.
    "      def #{method}\n#{src}\n      end\n"
  end

  <<~HEADER + bodies.join("\n") + <<~FOOTER
    # frozen_string_literal: true

    # GENERATED by `rake templates` from templates/*.erb. Do not edit by hand.

    module Pulpmesh
      class Site
        class Context
  HEADER
        end
      end
    end
  FOOTER
end

def generated_assets
  entries = Dir.glob(File.join(ROOT, "assets", "*.css")).sort.map do |path|
    name = File.basename(path, ".css").upcase.gsub("-", "_")
    # String#dump rather than a heredoc: the result is a plain double-quoted
    # literal that reproduces the file byte for byte whatever the css contains.
    "    #{name} = #{File.binread(path).dump}.freeze"
  end

  <<~HEADER + entries.join("\n") + <<~FOOTER
    # frozen_string_literal: true

    # GENERATED by `rake assets` from assets/*.css. Do not edit by hand.
    #
    # A compiled binary is standalone: there is no gem directory to read a
    # stylesheet from at runtime, so both sheets are compiled in as constants.

    module Pulpmesh
      module Assets
  HEADER
      end
    end
  FOOTER
end

# The html named entities, sourced from kramdown's own table so the fork decodes
# exactly what the gem decoded. Like Erubi, kramdown is a dev-machine tool here:
# the table is data, and the binary carries only the generated constant.
def generated_entities
  pairs = Kramdown::Utils::Entities::ENTITY_TABLE
          .select { |code, name| code.is_a?(Integer) && name.is_a?(String) }
          .map { |code, name| [name, code] }
          .sort_by { |name, _| name }

  lines = pairs.map { |name, code| "      #{name.inspect} => #{code}," }
  lines[-1] = lines[-1].chomp(",")

  <<~HEADER + lines.join("\n") + <<~FOOTER
    # frozen_string_literal: true

    # GENERATED by `rake entities` from kramdown's entity table. Do not edit by hand.

    module Pulpmesh
      module Markdown
        # Named html entity to unicode code point.
        ENTITIES = {
  HEADER
        }.freeze
      end
    end
  FOOTER
end
